mapper.update:
UPDATE dimension_artist_balance
SET balance = balance - #{amount}, update_time = NOW()
WHERE user_id = #{userId} AND balance >= #{amount}

UPDATE dimension_artist_balance
SET balance = balance + #{amount}, update_time = NOW()
WHERE user_id = #{userId}

UPDATE dimension_artist_balance
SET total_withdrawn = total_withdrawn + #{amount}, update_time = NOW()
WHERE user_id = #{userId}

mapper.select:
SELECT w.*, u.nickname, u.avatar
FROM dimension_artist_withdraw w
         LEFT JOIN dimension_user u ON u.id = w.user_id


        AND w.status = #{status}


ORDER BY w.id DESC
LIMIT #{pageNum}, #{pageSize}
